#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int compteur = 0; compteur < n; compteur++) {
        int a, b;
        char op;
        if (scanf(" %d %c %d", &a, &op, &b) != 3) return 0;
        if ((op == '/' || op == '%') && b == 0) {
            printf("ERREUR\n");
            continue;
        }
        if (op == '+') printf("%d\n", a + b);
        else if (op == '-') printf("%d\n", a - b);
        else if (op == '*') printf("%d\n", a * b);
        else if (op == '/') printf("%d\n", a / b);
        else if (op == '%') printf("%d\n", a % b);
    }
    return 0;
}

